provider "github" {
  organization = var.github_organization
}

resource "tls_private_key" "deploy_key" {
  algorithm = "RSA"
  rsa_bits  = "4096"
}

resource "null_resource" "private_key_file" {
  triggers = {
    deploy_key = tls_private_key.deploy_key.private_key_pem
  }

  provisioner "file" {
    content     = tls_private_key.deploy_key.private_key_pem
    destination = "~/${var.repo_name}_deploy_key.pem"

    connection {
      type        = "ssh"
      user        = "centos"
      private_key = var.terraform_ssh_key
      host        = var.server_ip
    }
  }

  provisioner "remote-exec" {
    inline = [
      "sudo mv ~/${var.repo_name}_deploy_key.pem /app/ssh_keys/",
      "sudo chmod 0400 /app/ssh_keys/${var.repo_name}_deploy_key.pem",
      "sudo chown app:app /app/ssh_keys/${var.repo_name}_deploy_key.pem",
    ]

    connection {
      type        = "ssh"
      user        = "centos"
      private_key = var.terraform_ssh_key
      host        = var.server_ip
    }
  }
}

resource "github_repository_deploy_key" "repo_deploy_key" {
  title      = "${var.env_name} Deploy Key"
  repository = var.repo_name
  key        = tls_private_key.deploy_key.public_key_openssh
  read_only  = var.read_only
}

{
    "name": "numbat-vscode-extension",
    "displayName": "Numbat",
    "description": "Syntax highlighting for the Numbat programming language",
    "version": "0.1.1",
    "license": "(MIT OR Apache-2.0)",
    "icon": "./assets/numbat-256x256.png",
    "engines": {
        "vscode": "^1.71.0"
    },
    "categories": [
        "Programming Languages"
    ],
    "keywords": [
        "language",
        "physics",
        "units",
        "calculation"
    ],
    "contributes": {
        "languages": [{
            "id": "numbat",
            "aliases": ["Numbat", "numbat"],
            "extensions": [".nbt"],
            "configuration": "./language-configuration.json",
            "icon": {
                "light": "./assets/numbat-64x64.png",
                "dark": "./assets/numbat-64x64.png"
            }
        }],
        "grammars": [{
            "language": "numbat",
            "scopeName": "source.numbat",
            "path": "./syntaxes/numbat.tmLanguage.json"
        }]
    },
    "scripts": {
        "vscode:package": "vsce package"
    },
    "devDependencies": {
        "@vscode/vsce": "3.3.2"
    },
    "vsce": {
        "skipLicense": true
    },
    "repository": {
        "type": "git",
        "url": "https://github.com/sharkdp/numbat.git"
    },
    "homepage": "https://github.com/sharkdp/numbat/blob/main/vscode-extension/README.md"
}

